<template><StatePanel v-if="pending" kind="loading" title="Loading bag" message="Retrieving your current items." /><StatePanel v-else-if="error || !identity" kind="error" title="Bag unavailable" message="This storefront could not be loaded." /><StorefrontFrame v-else :identity="identity" :navigation="navigation" :base="base"><div class="border-b pb-8"><h1 class="display-face text-5xl font-semibold tracking-[-0.03em] sm:text-6xl">Your bag</h1><p class="mt-3 text-muted-foreground">Every price and option is checked again by {{ identity.display_name }}.</p></div><StatePanel v-if="cart.loading" class="mt-8" kind="loading" title="Loading bag" message="Checking saved items." /><StatePanel v-else-if="cart.error" class="mt-8" kind="error" title="Bag unavailable" :message="cart.error" /><StatePanel v-else-if="!cart.cart?.items?.length" class="mt-10" title="Your bag is empty" message="Browse the shop to add a product."><ButtonAnchor :href="`${base}/shop`">Browse shop</ButtonAnchor></StatePanel><div v-else class="mt-10 grid gap-12 lg:grid-cols-[minmax(0,1fr)_24rem]"><section class="border-t"><article v-for="item in cart.cart.items" :key="item.public_id" class="grid gap-4 border-b py-6 sm:grid-cols-[1fr_auto] sm:items-center"><div><h2 class="text-lg font-extrabold">{{ item.name }}</h2><p v-if="item.metadata?.options?.length" class="mt-1 text-sm text-muted-foreground">{{ item.metadata.options.map((option) => option.name).join(' · ') }}</p><div class="mt-4 flex items-center gap-3"><div class="flex items-center rounded-md border"><Button variant="ghost" size="icon" :disabled="item.quantity <= 1 || updating === item.public_id" :aria-label="`Decrease ${item.name} quantity`" @click="update(item, item.quantity - 1)"><Minus class="h-4 w-4" /></Button><span class="w-9 text-center text-sm font-bold tabular-nums">{{ item.quantity }}</span><Button variant="ghost" size="icon" :disabled="updating === item.public_id" :aria-label="`Increase ${item.name} quantity`" @click="update(item, item.quantity + 1)"><Plus class="h-4 w-4" /></Button></div><Button variant="ghost" class="text-destructive" @click="cart.remove(item.public_id)">Remove</Button></div></div><strong class="text-lg">{{ money(Number(item.unit_price) * item.quantity) }}</strong></article></section><aside class="lg:sticky lg:top-28 lg:self-start"><h2 class="text-xl font-extrabold">Order summary</h2><form class="mt-5 flex gap-2" @submit.prevent="applyDiscount"><Input v-model.trim="discountCode" placeholder="Promotion code" aria-label="Promotion code" /><Button variant="outline" :disabled="applying">Apply</Button></form><p v-if="discountMessage" class="mt-2 text-sm" :class="discountError ? 'text-destructive' : 'text-primary'" role="status">{{ discountMessage }}</p><dl class="mt-6 divide-y border-y text-sm"><div class="flex justify-between py-3"><dt class="text-muted-foreground">Subtotal</dt><dd class="font-bold">{{ money(cart.cart.totals.subtotal) }}</dd></div><div v-if="Number(cart.cart.totals.discount_total)" class="flex justify-between py-3"><dt class="text-muted-foreground">Discount</dt><dd class="font-bold">−{{ money(cart.cart.totals.discount_total) }}</dd></div><div class="flex justify-between py-3"><dt class="text-muted-foreground">Tax</dt><dd class="font-bold">{{ money(cart.cart.totals.tax_total) }}</dd></div><div class="flex justify-between py-4 text-lg"><dt class="font-extrabold">Current total</dt><dd class="font-black">{{ money(cart.cart.totals.grand_total) }}</dd></div></dl><p class="mt-4 text-xs leading-5 text-muted-foreground">Shipping is selected and calculated during checkout.</p><ButtonAnchor :href="`${base}/checkout`" size="lg" class="mt-6 w-full">Checkout</ButtonAnchor><ButtonAnchor :href="`${base}/shop`" variant="outline" class="mt-2 w-full">Continue shopping</ButtonAnchor></aside></div></StorefrontFrame></template>
<script setup>
import { Minus, Plus } from 'lucide-vue-next'
definePageMeta({ layout: 'storefront' })
const route = useRoute()
const { identity, navigation, pending, error, siteBase: base } = useStorefrontContext(route.params.slug)
const cart = useCartStore()
const updating = ref('')
const applying = ref(false)
const discountCode = ref('')
const discountMessage = ref('')
const discountError = ref(false)
onMounted(async () => { await cart.load(route.params.slug); discountCode.value = cart.cart?.discount_code || '' })
const money = (value) => new Intl.NumberFormat('en-PH', { style: 'currency', currency: identity.value?.currency || 'PHP' }).format(Number(value || 0))
async function update(item, quantity) { updating.value = item.public_id; try { await cart.updateItem(item.public_id, { quantity }) } finally { updating.value = '' } }
async function applyDiscount() { applying.value = true; discountMessage.value = ''; try { await cart.applyDiscount(discountCode.value); discountMessage.value = discountCode.value ? 'Promotion applied.' : 'Promotion removed.'; discountError.value = false } catch (requestError) { discountMessage.value = requestError?.data?.discount_code?.[0] || requestError?.data?.error?.message || 'This promotion could not be applied.'; discountError.value = true } finally { applying.value = false } }
</script>
